// murmur3: MurmurHash3 (x86, 32-bit, seed 0) of 8 MiB of generated bytes.

fn main() {
    let n: i64 = 1 << 23;
    let data: Vec<u8> = (0..n).map(|i| ((i * 2654435761 >> 13) & 255) as u8).collect();
    let mut h = 0u32;
    for c in data.chunks_exact(4) {
        let k = u32::from_le_bytes([c[0], c[1], c[2], c[3]]);
        let k = k.wrapping_mul(0xcc9e2d51).rotate_left(15).wrapping_mul(0x1b873593);
        h = (h ^ k).rotate_left(13).wrapping_mul(5).wrapping_add(0xe6546b64);
    }
    h ^= n as u32;
    h = (h ^ h >> 16).wrapping_mul(0x85ebca6b);
    h = (h ^ h >> 13).wrapping_mul(0xc2b2ae35);
    h ^= h >> 16;
    println!("{h}");
}
